INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (1, 1, '彼は毎日野菜を食べる。', 'かれはまいにちやさいをたべる。', '그는 매일 야채를 먹는다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (2, 2, '私は毎日水を飲む。', 'わたしはまいにちみずをのむ。', '나는 매일 물을 마신다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (3, 3, '学生は本を見る。', 'がくせいはほんをみる。', '학생은 책을 본다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (4, 4, '学生は先生の話を聞く。', 'がくせいはせんせいのはなしをきく。', '학생은 선생님의 이야기를 듣는다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (5, 5, '友達と学校へ行く。', 'ともだちとがっこうへいく。', '친구와 학교에 간다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (6, 6, '先生が学校に来る。', 'せんせいががっこうにくる。', '선생님이 학교에 온다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (7, 7, '毎日学校へ行く。', 'まいにちがっこうへいく。', '매일 학교에 간다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (8, 8, '先生はとても元気だ。', 'せんせいはとてもげんきだ。', '선생님은 매우 건강하다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (9, 9, '学生は毎日勉強する。', 'がくせいはまいにちべんきょうする。', '학생은 매일 공부한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (10, 10, '友達は電車で来る。', 'ともだちはでんしゃでくる。', '친구는 전철로 온다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (11, 11, 'この本はとても大きい。', 'このほんはとてもおおきい。', '이 책은 매우 크다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (12, 12, '水を飲む。', 'みずをのむ。', '물을 마신다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (13, 13, '私は野菜が好きだ。', 'わたしはやさいがすきだ。', '나는 야채를 좋아한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (14, 14, '果物を食べる。', 'くだものをたべる。', '과일을 먹는다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (15, 15, 'この学校はとても大きい。', 'このがっこうはとてもおおきい。', '이 학교는 매우 크다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (16, 16, 'この本は小さい。', 'このほんはちいさい。', '이 책은 작다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (17, 17, '新しい先生が来る。', 'あたらしいせんせいがくる。', '새로운 선생님이 온다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (18, 18, 'この果物は高い。', 'このくだものはたかい。', '이 과일은 비싸다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (19, 19, '毎日学校で勉強する。', 'まいにちがっこうでべんきょうする。', '매일 학교에서 공부한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (20, 20, '今日は学校が休みだ。', 'きょうはがっこうがやすみだ。', '오늘은 학교가 쉬는 날이다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (21, 21, '学生は毎日教室で勉強する。', 'がくせいはまいにちきょうしつでべんきょうする。', '학생은 매일 교실에서 공부한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (22, 22, '父は毎日仕事に行く。', 'ちちはまいにちしごとにいく。', '아버지는 매일 일하러 간다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (23, 23, '電車で学校へ行く。', 'でんしゃでがっこうへいく。', '전철로 학교에 간다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (24, 24, '先生はいつも元気だ。', 'せんせいはいつもげんきだ。', '선생님은 항상 건강하다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (25, 25, '兄は毎日会社へ行く。', 'あにはまいにちかいしゃへいく。', '형/오빠는 매일 회사에 간다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (26, 26, '彼女は大学で経済を勉強する。', 'かのじょはだいがくでけいざいをべんきょうする。', '그녀는 대학에서 경제를 공부한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (27, 27, '家で本を読む。', 'いえでほんをよむ。', '집에서 책을 읽는다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (28, 28, '部屋はとても小さい。', 'へやはとてもちいさい。', '방은 매우 작다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (29, 29, '車で学校へ行く。', 'くるまでがっこうへいく。', '자동차로 학교에 간다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (30, 30, '自転車で友達の家へ行く。', 'じてんしゃでともだちのいえへいく。', '자전거로 친구 집에 간다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (31, 31, '今日は天気がいい。', 'きょうはてんきがいい。', '오늘은 날씨가 좋다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (32, 32, '今日は雨だ。', 'きょうはあめだ。', '오늘은 비가 온다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (33, 33, '今日は雪だ。', 'きょうはゆきだ。', '오늘은 눈이 온다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (34, 34, '朝は忙しい。', 'あさはいそがしい。', '아침은 바쁘다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (35, 35, '夜は静かだ。', 'よるはしずかだ。', '밤은 조용하다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (36, 36, '今、忙しい。', 'いま、いそがしい。', '지금 바쁘다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (37, 37, '時間がない。', 'じかんがない。', '시간이 없다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (38, 38, '新しい本を買う。', 'あたらしいほんをかう。', '새 책을 산다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (39, 39, '友達に本を売る。', 'ともだちにほんをうる。', '친구에게 책을 판다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (40, 40, '学生は毎日本を読む。', 'がくせいはまいにちほんをよむ。', '학생은 매일 책을 읽는다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (41, 41, '学生は本に名前を書く。', 'がくせいはほんになまえをかく。', '학생은 책에 이름을 쓴다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (42, 42, '先生と話す。', 'せんせいとはなす。', '선생님과 이야기한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (43, 43, '学生が立つ。', 'がくせいがたつ。', '학생이 선다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (44, 44, '先生の前に座る。', 'せんせいのまえにすわる。', '선생님 앞에 앉는다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (45, 45, '夜早く寝る。', 'よるはやくねる。', '밤에 일찍 잔다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (46, 46, '朝早く起きる。', 'あさはやくおきる。', '아침에 일찍 일어난다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (47, 47, '今日は仕事を休む。', 'きょうはしごとをやすむ。', '오늘은 일을 쉰다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (48, 48, '学生は毎日走る。', 'がくせいはまいにちはしる。', '학생은 매일 달린다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (49, 49, '友達と泳ぐ。', 'ともだちとおよぐ。', '친구와 수영한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (50, 50, '友達と歌う。', 'ともだちとうたう。', '친구와 노래한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (51, 51, 'この果物は甘い。', 'このくだものはあまい。', '이 과일은 달다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (52, 52, 'この野菜は辛い。', 'このやさいはからい。', '이 야채는 맵다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (53, 53, '今日はとても暑い。', 'きょうはとてもあつい。', '오늘은 매우 덥다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (54, 54, '今日は寒い。', 'きょうはさむい。', '오늘은 춥다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (55, 55, '先生は毎日忙しい。', 'せんせいはまいにちいそがしい。', '선생님은 매일 바쁘다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (56, 56, '学校はとても楽しい。', 'がっこうはとてもたのしい。', '학교는 매우 즐겁다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (57, 57, 'この本は難しい。', 'このほんはむずかしい。', '이 책은 어렵다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (58, 58, 'この本は易しい。', 'このほんはやさしい。', '이 책은 쉽다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (59, 59, 'この部屋は静かだ。', 'このへやはしずかだ。', '이 방은 조용하다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (60, 60, 'この学校は有名だ。', 'このがっこうはゆうめいだ。', '이 학교는 유명하다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (61, 61, '電車は便利だ。', 'でんしゃはべんりだ。', '전철은 편리하다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (62, 62, '先生はとても親切だ。', 'せんせいはとてもしんせつだ。', '선생님은 매우 친절하다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (63, 63, 'いい経験になる。', 'いいけいけんになる。', '좋은 경험이 된다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (64, 64, '会議の準備をする。', 'かいぎのじゅんびをする。', '회의 준비를 한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (65, 65, '先生が説明する。', 'せんせいがせつめいする。', '선생님이 설명한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (66, 66, '学生が質問する。', 'がくせいがしつもんする。', '학생이 질문한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (67, 67, '会議の予定を決める。', 'かいぎのよていをきめる。', '회의 예정을 정한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (68, 68, '今日は会議がある。', 'きょうはかいぎがある。', '오늘은 회의가 있다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (69, 69, '友達に連絡する。', 'ともだちにれんらくする。', '친구에게 연락한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (70, 70, '毎日練習する。', 'まいにちれんしゅうする。', '매일 연습한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (71, 71, '会議に参加する。', 'かいぎにさんかする。', '회의에 참가한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (72, 72, '電車が到着する。', 'でんしゃがとうちゃくする。', '전철이 도착한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (73, 73, '朝早く出発する。', 'あさはやくしゅっぱつする。', '아침 일찍 출발한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (74, 74, '予定を決める。', 'よていをきめる。', '예정을 정한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (75, 75, '毎日勉強を続ける。', 'まいにちべんきょうをつづける。', '매일 공부를 계속한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (76, 76, '会議が始まる。', 'かいぎがはじまる。', '회의가 시작된다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (77, 77, '会議が終わる。', 'かいぎがおわる。', '회의가 끝난다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (78, 78, '予定を変える。', 'よていをかえる。', '예정을 바꾼다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (79, 79, '毎日新しい単語を覚える。', 'まいにちあたらしいたんごをおぼえる。', '매일 새로운 단어를 외운다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (80, 80, '彼はよく忘れる。', 'かれはよくわすれる。', '그는 자주 잊는다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (81, 81, 'いい気持ちだ。', 'いいきもちだ。', '좋은 기분이다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (82, 82, '彼女の性格は親切だ。', 'かのじょのせいかくはしんせつだ。', '그녀의 성격은 친절하다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (83, 83, 'この仕事は危険だ。', 'このしごとはきけんだ。', '이 일은 위험하다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (84, 84, 'この電車は安全だ。', 'このでんしゃはあんぜんだ。', '이 전철은 안전하다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (85, 85, '環境について先生と話す。', 'かんきょうについてせんせいとはなす。', '환경에 대해 선생님과 이야기한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (86, 86, '大学で経済を勉強する。', 'だいがくでけいざいをべんきょうする。', '대학에서 경제를 공부한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (87, 87, '政治は難しい。', 'せいじはむずかしい。', '정치는 어렵다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (88, 88, '学校も社会の一部だ。', 'がっこうもしゃかいのいちぶだ。', '학교도 사회의 일부다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (89, 89, '文化を勉強する。', 'ぶんかをべんきょうする。', '문화를 공부한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (90, 90, '歴史を勉強する。', 'れきしをべんきょうする。', '역사를 공부한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (91, 91, '天気は気持ちに影響する。', 'てんきはきもちにえいきょうする。', '날씨는 기분에 영향을 준다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (92, 92, '原因を説明する。', 'げんいんをせつめいする。', '원인을 설명한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (93, 93, '会議の結果を説明する。', 'かいぎのけっかをせつめいする。', '회의 결과를 설명한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (94, 94, '原因を解決する。', 'げんいんをかいけつする。', '원인을 해결한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (95, 95, '経済が発展する。', 'けいざいがはってんする。', '경제가 발전한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (96, 96, '学生が増加する。', 'がくせいがぞうかする。', '학생이 증가한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (97, 97, '学生が減少する。', 'がくせいがげんしょうする。', '학생이 감소한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (98, 98, '先生が判断する。', 'せんせいがはんだんする。', '선생님이 판단한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (99, 99, '学生が増加する傾向がある。', 'がくせいがぞうかするけいこうがある。', '학생이 증가하는 경향이 있다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (100, 100, '電車は便利な手段だ。', 'でんしゃはべんりなしゅだんだ。', '전철은 편리한 수단이다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (101, 101, '難しい概念を説明する。', 'むずかしいがいねんをせつめいする。', '어려운 개념을 설명한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (102, 102, '経済の分野を勉強する。', 'けいざいのぶんやをべんきょうする。', '경제 분야를 공부한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (103, 103, '環境の現象を説明する。', 'かんきょうのげんしょうをせつめいする。', '환경 현상을 설명한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (104, 104, '経済は重要な要素だ。', 'けいざいはじゅうようなようそだ。', '경제는 중요한 요소다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (105, 105, '前提を説明する。', 'ぜんていをせつめいする。', '전제를 설명한다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (106, 106, '説明に矛盾がある。', 'せつめいにむじゅんがある。', '설명에 모순이 있다.');
INSERT IGNORE INTO example_sentences (id, word_id, sentence_jp, sentence_reading, sentence_meaning) VALUES (107, 107, 'この概念は抽象的だ。', 'このがいねんはちゅうしょうてきだ。', '이 개념은 추상적이다.');
